#!/usr/bin/env python3
# Turns an 8x16 PSF2 font (e.g. the kbd ones in /usr/lib/kbd/consolefonts) into
# the C array the console uses. Run by hand, the generated file is checked in:
#
#     tools/psf2c.py /usr/lib/kbd/consolefonts/default8x16.psfu.gz > kernel/src/font.c

import gzip
import struct
import sys

PSF2_MAGIC = 0x864AB572


def main():
    path = sys.argv[1]
    opener = gzip.open if path.endswith(".gz") else open
    with opener(path, "rb") as f:
        data = f.read()

    magic, _version, header_size, _flags, count, char_size, height, width = struct.unpack_from("<8I", data)
    if magic != PSF2_MAGIC:
        sys.exit("not a PSF2 font")
    if width != 8 or height != 16 or char_size != 16:
        sys.exit(f"need an 8x16 font, this one is {width}x{height}")

    # the console indexes by byte, anything past 256 glyphs is unused
    count = min(count, 256)
    glyphs = data[header_size:header_size + count * char_size]

    out = sys.stdout
    out.write(f"// generated by tools/psf2c.py from {path.rsplit('/', 1)[-1]} (kbd, GPL-2.0-or-later)\n\n")
    out.write("#include <stdint.h>\n\n#include \"font.h\"\n\n")
    out.write(f"const uint8_t font_8x16[{count}][FONT_HEIGHT] = {{\n")
    for i in range(count):
        rows = glyphs[i * char_size:(i + 1) * char_size]
        out.write("    {" + ", ".join(f"0x{b:02X}" for b in rows) + "},\n")
    out.write("};\n")


if __name__ == "__main__":
    main()
